//! Receiver-side custom-format conversion. Unknown foreign formats are discarded.
use oink_foundation::clipboard::{ClipData, ClipPlatform, Sensitivity};

pub const ITEM_MAX: usize = 256 * 1024 * 1024;
pub const MAC_MARKERS: &[&str] = &[
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
];
pub const WIN_MARKERS: &[&str] = &[
    "Clipboard Viewer Ignore",
    "ExcludeClipboardContentFromMonitorProcessing",
    "CanIncludeInClipboardHistory",
    "CanUploadToCloudClipboard",
];

/// Add only documented, byte-format-aware conversions here.
#[derive(Debug)]
pub struct FormatMapping {
    pub source: ClipPlatform,
    pub name: &'static str,
    pub target: ClipPlatform,
    pub convert: fn(&[u8]) -> Option<ClipData>,
}
pub const CROSS_PLATFORM_MAPPINGS: &[FormatMapping] = &[];

pub fn custom(platform: ClipPlatform, name: &str, bytes: Vec<u8>) -> ClipData {
    ClipData::Custom {
        platform,
        name: name.into(),
        bytes,
    }
}

fn name_matches(platform: ClipPlatform, a: &str, b: &str) -> bool {
    match platform {
        ClipPlatform::Mac => a == b,
        ClipPlatform::Windows => a.eq_ignore_ascii_case(b),
        ClipPlatform::Unknown => false,
    }
}
fn canonical_marker(platform: ClipPlatform, name: &str) -> Option<&'static str> {
    if platform == ClipPlatform::Mac {
        match name {
            "de.petermaurer.TransientPasteboardType" => return Some(MAC_MARKERS[0]),
            "com.agilebits.onepassword" => return Some(MAC_MARKERS[1]),
            "com.typeit4me.clipping" | "Pasteboard generator type" => return Some(MAC_MARKERS[2]),
            _ => {}
        }
    }
    let names = match platform {
        ClipPlatform::Mac => MAC_MARKERS,
        ClipPlatform::Windows => WIN_MARKERS,
        ClipPlatform::Unknown => return None,
    };
    names.iter().copied().find(|n| name_matches(platform, n, name))
}
pub fn is_marker(platform: ClipPlatform, name: &str) -> bool {
    canonical_marker(platform, name).is_some()
}

/// Retain exact same-system bytes, map known privacy semantics, then consult the
/// extension table. Sensitivity supplies a marker only when none is explicit.
pub fn for_platform(items: &[ClipData], target: ClipPlatform, sensitivity: Sensitivity) -> Vec<ClipData> {
    let mut out = Vec::new();
    let mut explicit = false;
    for item in items {
        let ClipData::Custom { platform, name, bytes } = item else {
            out.push(item.clone());
            continue;
        };
        let marker = canonical_marker(*platform, name);
        explicit |= marker.is_some();
        if *platform == target {
            out.push(item.clone());
        } else if let Some(marker) = marker {
            match target {
                ClipPlatform::Mac => {
                    let marker = match marker {
                        "Clipboard Viewer Ignore" => Some(MAC_MARKERS[0]),
                        "ExcludeClipboardContentFromMonitorProcessing" => Some(MAC_MARKERS[1]),
                        "CanIncludeInClipboardHistory" if bytes.get(..4) == Some(&[0, 0, 0, 0]) => Some(MAC_MARKERS[1]),
                        _ => None,
                    };
                    if let Some(n) = marker {
                        out.push(custom(target, n, vec![]));
                    }
                }
                ClipPlatform::Windows => {
                    let names: &[&str] = match marker {
                        "org.nspasteboard.TransientType" => &[WIN_MARKERS[0]],
                        "org.nspasteboard.ConcealedType" => &[WIN_MARKERS[1], WIN_MARKERS[2]],
                        _ => &[],
                    };
                    for n in names {
                        out.push(custom(target, n, vec![0; 4]));
                    }
                }
                ClipPlatform::Unknown => {}
            }
        } else if let Some(mapping) = CROSS_PLATFORM_MAPPINGS
            .iter()
            .find(|m| m.source == *platform && m.target == target && name_matches(*platform, m.name, name))
            && let Some(converted) = (mapping.convert)(bytes)
        {
            out.push(converted);
        }
    }
    if !explicit {
        let names: &[&str] = match (target, sensitivity) {
            (ClipPlatform::Mac, Sensitivity::Transient) => &[MAC_MARKERS[0]],
            (ClipPlatform::Mac, Sensitivity::Concealed) => &[MAC_MARKERS[1]],
            (ClipPlatform::Mac, Sensitivity::AutoGenerated) => &[MAC_MARKERS[2]],
            (ClipPlatform::Windows, Sensitivity::Transient) => &[WIN_MARKERS[0]],
            (ClipPlatform::Windows, Sensitivity::Concealed) => &[WIN_MARKERS[1], WIN_MARKERS[2]],
            _ => &[],
        };
        for name in names {
            out.push(custom(
                target,
                name,
                if target == ClipPlatform::Windows {
                    vec![0; 4]
                } else {
                    vec![]
                },
            ));
        }
    }
    out
}

/// Standard formats, unsafe process-local protocols and obsolete aliases must
/// never be recreated as opaque data (including untrusted incoming names).
pub fn mac_custom(name: &str) -> bool {
    !matches!(
        name,
        "public.utf8-plain-text"
            | "public.html"
            | "public.rtf"
            | "public.png"
            | "public.tiff"
            | "public.file-url"
            | "NSStringPboardType"
            | "NSHTMLPboardType"
            | "NSRTFPboardType"
            | "NSTIFFPboardType"
            | "NSFilenamesPboardType"
            | "public.utf16-plain-text"
            | "public.utf16-external-plain-text"
            | "com.apple.traditional-mac-plain-text"
            | "de.petermaurer.TransientPasteboardType"
            | "com.agilebits.onepassword"
            | "com.typeit4me.clipping"
            | "Pasteboard generator type"
    ) && !name.starts_with("com.hachiwii.oink.")
        && !name.starts_with("CorePasteboardFlavorType ")
        && !name.starts_with("com.apple.pasteboard.promised-")
        && !name.is_empty()
        && !name.contains('\0')
}
pub fn windows_custom(name: &str) -> bool {
    ![
        "HTML Format",
        "Rich Text Format",
        "PNG",
        "FileGroupDescriptorW",
        "FileGroupDescriptor",
        "FileContents",
        "Preferred DropEffect",
        "Performed DropEffect",
        "Logical Performed DropEffect",
        "Paste Succeeded",
        "Object Descriptor",
        "Link Source Descriptor",
        "Link Source",
        "Embed Source",
        "Embedded Object",
        "Ole Private Data",
        "DataObject",
        "OleClipboardPersistOnFlush",
    ]
    .iter()
    .any(|n| name.eq_ignore_ascii_case(n))
        && !name.is_empty()
        && !name.contains('\0')
        && !name.starts_with("Oink")
}

#[cfg(all(test, debug_assertions))]
mod tests {
    use super::*;
    #[test]
    fn windows_registered_marker_names_ignore_case_but_keep_original_bytes() {
        let items = vec![
            custom(ClipPlatform::Windows, "canincludeinclipboardhistory", vec![1, 0, 0, 0]),
            custom(ClipPlatform::Windows, "CLIPBOARD VIEWER IGNORE", vec![7, 9]),
        ];
        assert_eq!(
            for_platform(&items, ClipPlatform::Windows, Sensitivity::Transient),
            items
        );
        assert_eq!(
            for_platform(&items, ClipPlatform::Mac, Sensitivity::Transient),
            vec![custom(ClipPlatform::Mac, MAC_MARKERS[0], vec![])]
        );
    }

    #[test]
    fn exact_markers_and_foreign_filter() {
        let items = vec![
            custom(ClipPlatform::Windows, WIN_MARKERS[2], vec![1, 0, 0, 0]),
            custom(ClipPlatform::Windows, WIN_MARKERS[3], vec![0; 4]),
            custom(ClipPlatform::Mac, "example.private", vec![42]),
        ];
        assert_eq!(
            for_platform(&items, ClipPlatform::Windows, Sensitivity::Concealed),
            items[..2]
        );
        assert_eq!(
            for_platform(&items, ClipPlatform::Mac, Sensitivity::Concealed),
            items[2..]
        );
    }
    #[test]
    fn simultaneous_privacy_markers_map_independently() {
        let items = MAC_MARKERS
            .iter()
            .map(|n| custom(ClipPlatform::Mac, n, vec![7]))
            .collect::<Vec<_>>();
        assert_eq!(for_platform(&items, ClipPlatform::Mac, Sensitivity::Transient), items);
        let win = for_platform(&items, ClipPlatform::Windows, Sensitivity::Transient);
        assert_eq!(win.len(), 3);
        assert!(
            !win.iter()
                .any(|d| matches!(d, ClipData::Custom { name, .. } if name == WIN_MARKERS[3]))
        );
    }
    #[test]
    fn reserved_names_are_not_opaque() {
        assert!(!mac_custom("public.file-url"));
        assert!(!mac_custom("NSStringPboardType"));
        assert!(!windows_custom("FileContents"));
        assert!(windows_custom("Clipboard Viewer Ignore"));
        assert!(mac_custom(MAC_MARKERS[0]));
    }
}
